node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return null}}
const code=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")

const N=rd("lib/spaces/profile-nav.ts")
if(N===null)fail("the Space profile nav is gone")
const nc=code(N)
if(/label: .Discussion./.test(nc))fail("the Space menu grew the Discussion row back: two menu rows over one subject, which is the defect this row closed")
if(nc.indexOf("/discussion")>=0)fail("the Space menu links a dedicated discussion route again, which is the same second row wearing a different label")
if(!/label: .Circles./.test(nc))fail("the Circles row is gone from the menu, so the community page this row built has no door at all (control: this arm must keep passing for the two above to mean anything)")

const P="app/(main)/spaces/[slug]/(profile)/circles/page.tsx"
const C=rd(P)
if(C===null)fail("the Space Circles tab is gone")
if(/<CircleFeed[\s/>]/.test(code(C)))fail("the Circles tab mounts a Circle feed again: the Space conversation is the Community wall (ADR-1938), so this is two pages over one subject")
const W=rd("app/(main)/spaces/[slug]/(profile)/community/page.tsx")
if(W===null)fail("the Space Community wall is gone, so the conversation has no page")
const F=rd("app/(main)/spaces/[slug]/(profile)/discussion/page.tsx")
if(F===null)fail("the discussion segment is gone: it is a RESERVED page slug already sent out in notifications, so deleting it lets an operator page shadow it and 404s every old link")
const fc=code(F)
if(!/redirect\(/.test(fc))fail("the discussion segment no longer forwards, so the folded word lost its address")
if(fc.indexOf("/community")<0)fail("the discussion segment forwards somewhere other than the Community wall")
if(/<CircleFeed[\s/>]/.test(fc))fail("the discussion segment mounts a feed of its own: two pages over one subject")

const S=rd("lib/spaces/profile-pages.ts")
if(S===null)fail("profile-pages is gone")
const sc=code(S)
const i=sc.indexOf("RESERVED_PAGE_SLUGS")
if(i<0)fail("the reserved page slug set is gone")
const seg=sc.slice(i,sc.indexOf("])",i))
if(!/.discussion.,/.test(seg))fail("discussion left RESERVED_PAGE_SLUGS, so an operator can create a custom page that shadows a URL already sent out in notifications")
console.log("LIVE-523 ok")'
